fn zero_pivot_column(
    &self,
    a: &BasicMatrix<F>,
    column: usize,
    operation: &'static str,
    conj: &dyn Fn(&F) -> Result<F, ExactFieldError>,
) -> Result<Option<LdltOutcome<F>>, ExactFieldError> {
    for row in (column + 1)..a.rows() {
        let schur = self.schur(a, row, column, conj)?;
        if schur.try_is_zero()? {
            let diagonal = self.schur(a, row, row, conj)?;
            let x = zero_pivot_coefficient(operation, &diagonal, &schur)?;
            let rhs = sparse_vector(a.rows(), &[(column, x), (row, F::one())])?;
            let witness = solve_unit_lower_adjoint(&self.lower, rhs, conj)?;
            return Ok(Some(LdltOutcome::ZeroPivotWithNonzeroColumn {
                step: column,
                row,
                witness,
            }));
        }
    }
    Ok(None)
}

